import { useEffect, useRef, useState } from "react";

import {
  attachmentProblem,
  readAttachment,
  releaseAttachment,
  toPayload,
  type StagedAttachment,
} from "../../lib/attachments";
import {
  HELP_TEXT,
  IMPACT_PROMPT,
  STUDIO_COMMANDS,
  isSlashCommand,
  type StudioCommand,
} from "../../lib/commands";
